WITH scored AS (SELECT id, customer_id, plan, start_date, end_date, monthly_fee, status, RANK() OVER (PARTITION BY plan ORDER BY monthly_fee DESC NULLS LAST) AS monthly_fee_rank, AVG(monthly_fee) OVER (PARTITION BY customer_id, plan ORDER BY end_date ASC, id ASC ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS monthly_fee_avg_5, AVG(monthly_fee) OVER (PARTITION BY plan ORDER BY monthly_fee ASC, id ASC ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS monthly_fee_avg_3_prior, NTILE(5) OVER (PARTITION BY plan ORDER BY monthly_fee DESC, id ASC) AS monthly_fee_bucket FROM subscriptions WHERE start_date <= '2025-04-01') SELECT status, SUM(monthly_fee_avg_5) AS total_monthly_fee_avg_5, ROUND(AVG(monthly_fee_avg_5), 2) AS avg_monthly_fee_avg_5, APPROX_PERCENTILE(monthly_fee_rank, ARRAY(0.25, 0.5, 0.75)) AS monthly_fee_rank_quartiles FROM scored GROUP BY status HAVING avg_monthly_fee_avg_5 < 1000000;
